    return sum(abs(x - mean) for x in numbers) / len(numbers)

def find_topmost_carpet(n, carpets, point) -> int:
    topmost_carpet = -1
    for i in range(n):
        a, b, g, k = carpets[i]
        if a <= point[0] <= a + g and b <= point[1] <= b + k:
            if topmost_carpet == -1 or (a + g) > (topmost_carpet[0] + topmost_carpet[2]):
                topmost_carpet = (a, b, a + g, b + k)
    return topmost_carpet[3] if topmost_carpet != -1 else -1

