def cantor_numbering(N: int) -> str:
    if N == 0:
        return "0/1"
    elif N == 1:
        return "1/1"
    else:
        numerator = 2 * (N // 3)
        denominator = 2 * (N % 3) + 1
        return f"{numerator}/{denominator}"

