def verify_isbn(isbn: str) -> str:
    if len(isbn) != 13 or not isbn[12].isdigit() and isbn[12] != 'X':
        return "Invalid ISBN format"

    def calculate_checksum(isbn: str) -> int:
        weights = [1, 3, 1, 3, 1, 3, 1, 3, 1, 3, 1, 3, 1]
        total = sum(int(digit) * weight for digit, weight in zip(isbn[:-1], weights))
        if isbn[-1] == 'X':
            total += 10
        return total % 11

    calculated_checksum = calculate_checksum(isbn)
    if calculated_checksum == 10:
        calculated_checksum = 'X'

    if calculated_checksum == int(isbn[-1]):
        return "Right"
    else:
        return isbn[:-1] + str(calculated_checksum)

