def count_passing_ways(n: int, m: int) -> int:
    if m == 0:
        return 1
    if n == 1:
        return 0

    # Initialize the dp array
    dp = [[0] * (m + 1) for _ in range(n)]

    # Base case: There's one way to stay in the same position after 0 passes
    for i in range(n):
        dp[i][0] = 1

    # Fill the dp array
    for i in range(1, n):
        for j in range(1, m + 1):
            dp[i][j] = dp[(i - 1) % n][j - 1] + dp[(i + 1) % n][j - 1]

    return dp[0][m]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a 2D array to store the maximum happiness values
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the dp array
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            price, importance = items[i - 1]
            if price <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - price] + importance)
            else:
                dp[i][j] = dp[i - 1][j]

    # The maximum happiness value that can be achieved is in dp[m][n]
    return dp[m][n]

def max_energy(beads):
    n = len(beads)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = beads[i]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = max(dp[i][k] + dp[k + 1][j] * beads[i] * beads[k + 1] for k in range(i, j))

    return dp[0][n - 1]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    result = []
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        if i == n:
            term = f"{abs(coeff)}x^{n}"
        elif i == 0:
            term = f"{abs(coeff)}"
        else:
            term = f"{abs(coeff)}x^{i}"
        if coeff < 0:
            term = f"-{term}"
        result.append(term)
    return ' + '.join(result)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for i in range(len(encoded)):
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        elif mapping[encoded[i]] != original[i]:
            return "Failed"

    decoded = ""
    for char in message:
        if char in mapping:
            decoded += mapping[char]
        else:
            return "Failed"

    return decoded

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        return None  # No prime factors for non-positive integers or 1

    largest_factor = None

    # Check for factors from 2 up to the square root of n
    for i in range(2, int(n**0.5) + 1):
        while n % i == 0:
            largest_factor = i
            n //= i

    # If n is a prime number greater than 2
    if n > 2:
        largest_factor = n

    return largest_factor

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i - 1][j]
            if i >= x:
                dp[i][j] += dp[i - x][j - 1]
    return dp[n][k]

