def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set()

    while queue:
        current, steps = queue.popleft()
        if current == B:
            return steps

        if steps > 10:
            return "NO ANSWER!"

        for rule in rules:
            if rule[0] in current:
                new_string = current.replace(rule[0], rule[1])
                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, steps + 1))

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

