    return total_savings

def minimum_students_to_leave(heights):
    n = len(heights)
    left = 0
    right = n - 1
    count = 0

    while left < right:
        if heights[left] < heights[right]:
            left += 1
        else:
            right -= 1
            count += 1

    return count

def min_groups(w, n, prices):
    prices.sort()
    groups = 0
    current_group_price = 0

    for price in prices:
        if current_group_price + price <= w:
            current_group_price += price
        else:
            groups += 1
            current_group_price = price

    return groups + 1  # Add one more group for the last incomplete group

def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14
    else:
        # Recursive relation for double-disc Hanoi Towers
        return 2 * hanoi_double_iterative(n - 1) + 4

def total_smoked_cigarettes(n, k):
